 1	method find_min_index(a : array<int>, s: int, e: int) returns (min_i: int)
 2	requires a.Length > 0
 3	requires 0 <= s < a.Length
 4	requires e <= a.Length
 5	requires e > s
 6	
 7	ensures min_i >= s 
 8	ensures min_i < e 
 9	ensures forall k: int :: s <= k < e ==> a[min_i] <= a[k]
10	{
11	    min_i := s;
12	    var i : int := s;  
13	
14	    while i < e 
15	    decreases e - i // loop variant
16	    invariant s <= i <= e
17	    invariant s <= min_i < e
18	    // unnecessary invariant
19	    // invariant i < e ==> min_i <= i 
20	    invariant forall k: int :: s <= k < i ==> a[min_i] <= a[k]
21	    {
22	        if a[i] <= a[min_i] {
23	            min_i := i;
24	        }
25	        i := i + 1;
26	    }
27	
28	}
29	
30	
31	
32	predicate is_sorted(ss: seq<int>)
33	{
34	    forall i, j: int:: 0 <= i <= j < |ss| ==> ss[i] <= ss[j]
35	}
36	
37	predicate is_permutation(a:seq<int>, b:seq<int>)
38	decreases |a|
39	decreases |b|
40	{
41	    |a| == |b|  && 
42	    ((|a| == 0 && |b| == 0) ||  
43	    exists i,j : int :: 0<=i<|a| &&  0<=j<|b|  && a[i] == b[j] && is_permutation(a[0..i] + if i < |a| then a[i+1..] else [], b[0..j] + if j < |b| then  b[j+1..] else []))
44	}
45	
46	
