48	// decreases |a|
49	// decreases |b|
50	// {
51	//     |a| == |b|  && ((|a| == 0 && |b| == 0) ||  exists i,j : int :: 0<=i<|a| &&  0<=j<|b|  && a[i] == b[j] && is_permutation(a[0..i] + a[i+1..], b[0..j] + b[j+1..]))
52	// }
53	
54	predicate is_permutation2(a:seq<int>, b:seq<int>)
55	{
56	    multiset(a) == multiset(b)
57	}
58	
59	
60	
61	method selection_sort(ns: array<int>) 
62	requires ns.Length >= 0
63	ensures is_sorted(ns[..])
64	ensures is_permutation2(old(ns[..]), ns[..])
65	modifies ns
66	{
67	    var i: int := 0;
68	    var l: int := ns.Length;
69	    while i < l
70	    decreases l - i
71	    invariant 0 <= i <= (l) + 1
72	    invariant is_permutation2(old(ns[..]), ns[..])
73	    invariant forall k, kk: int :: 0 <= k < i  && i <= kk < ns.Length ==> ns[k] <= ns[kk] // left els must be lesser than right ones
74	    invariant is_sorted(ns[..i])
75	    {
76	        var min_i: int := find_min_index(ns, i, ns.Length);
77	        ns[i], ns[min_i] := ns[min_i], ns[i];
78	        i := i + 1;
79	    }
80	
81	}

